<?php
declare(strict_types=1);
use ImAuthenticator\Security;use ImAuthenticator\Web;
$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$admin=$auth->requireAdmin();$message='';if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);foreach($db->all('SELECT id FROM system_roles')as$r){$id=(int)$r['id'];$level=max(1,min(3,(int)($_POST['level'][$id]??1)));$mfa=isset($_POST['mfa'][$id])?1:0;$before=$db->one('SELECT * FROM role_security_policies WHERE system_role_id=?',[$id]);$db->execute('INSERT INTO role_security_policies(system_role_id,require_mfa,minimum_auth_level) VALUES(?,?,?) ON DUPLICATE KEY UPDATE require_mfa=VALUES(require_mfa),minimum_auth_level=VALUES(minimum_auth_level)',[$id,$mfa,$level]);$after=$db->one('SELECT * FROM role_security_policies WHERE system_role_id=?',[$id]);if($before!=$after)$audit->write('role.security_policy.updated','success',(int)$admin['id'],null,null,null,['role_id'=>$id,'before'=>$before,'after'=>$after]);}$message='<div class="alert success">Polityki ról zostały zapisane.</div>';}$rows='';foreach($db->all('SELECT r.*,rsp.require_mfa,rsp.minimum_auth_level FROM system_roles r LEFT JOIN role_security_policies rsp ON rsp.system_role_id=r.id ORDER BY r.name')as$r){$id=(int)$r['id'];$level=(int)($r['minimum_auth_level']??1);$rows.='<tr><td><strong>'.Web::e($r['name']).'</strong></td><td><label class="check"><input type="checkbox" name="mfa['.$id.']" '.((bool)($r['require_mfa']??false)?'checked':'').'> Wymagaj MFA</label></td><td><select name="level['.$id.']"><option value="1" '.($level===1?'selected':'').'>1</option><option value="2" '.($level===2?'selected':'').'>2</option><option value="3" '.($level===3?'selected':'').'>3</option></select></td></tr>';}$content='<div class="page-head"><div><h1>MFA per rola</h1><p>Najbardziej restrykcyjna polityka ze wszystkich ról użytkownika ma pierwszeństwo.</p></div></div>'.$message.'<form method="post" class="card"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><table><thead><tr><th>Rola</th><th>MFA</th><th>Minimalny auth level</th></tr></thead><tbody>'.$rows.'</tbody></table><button class="primary">Zapisz</button></form>';Web::page('MFA per rola',$content,$admin);
